-- Migration 015: Détails élèves (assiduité, notes, discipline, cantine, projet, santé, réclamations, RDV)
-- Sous-objets imbriqués (evaluations, responsables, historiqueFlux, messages, competences, timeline,
-- objectifsChecklist, visits, compteRendu) restent en jsonb : toujours lus/écrits en bloc par l'UI,
-- jamais filtrés/agrégés côté SQL.

drop table if exists public.student_events cascade;
drop table if exists public.student_notes cascade;
drop table if exists public.student_conduite cascade;
drop table if exists public.student_cantine cascade;
drop table if exists public.student_sante cascade;
drop table if exists public.student_extras cascade;

create table public.student_extras (
  student_id text primary key references public.students(id) on delete cascade,
  conduite numeric not null default 20,
  moyenne numeric not null default 15,
  events jsonb not null default '[]'::jsonb,
  notes jsonb not null default '[]'::jsonb,
  discipline jsonb not null default '[]'::jsonb,
  cantine jsonb not null default '{}'::jsonb,
  projet jsonb not null default '{}'::jsonb,
  sante jsonb not null default '{"visits":[]}'::jsonb,
  reclamations jsonb not null default '[]'::jsonb,
  rendez_vous jsonb not null default '[]'::jsonb
);

